import{_ as r,a0 as p,w as s,s as n,ao as u,I as a,x as l,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何使用多種編程語言而又不失理智 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用多種編程語言而又不失理智 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用多種編程語言而又不失理智 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用多種編程語言而又不失理智 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181126 How to use multiple programming languages without losing your mind","title":"如何使用多種編程語言而又不失理智","tag":"201811","desc":""},"relativePath":"201811/20181126 How to use multiple programming languages without losing your mind.md","filePath":"[post].md"}'),g={name:"201811/20181126 How to use multiple programming languages without losing your mind.md"};function m(d,t,f,T,C,h){const o=p("Link");return s(),n("div",null,[t[15]||(t[15]=u('<h1 id="如何使用多種編程語言而又不失理智" tabindex="-1">如何使用多種編程語言而又不失理智 <a class="header-anchor" href="#如何使用多種編程語言而又不失理智" aria-label="Permalink to “如何使用多種編程語言而又不失理智”">​</a></h1><blockquote><p>多語言編程環境是一把雙刃劍，既帶來好處，也帶來可能威脅組織的複雜性。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/books_programming_languages.jpg?itok=KJcdnXM2" alt=""></p><p>如今，隨着各種不同的編程語言的出現，許多組織已經變成了<ruby>數字多語種組織<rt>digital polyglots</rt></ruby>。開源打開了一個語言和技術堆棧的世界，開發人員可以使用這些語言和技術堆棧來完成他們的任務，包括開發、支持過時的和現代的軟件應用。</p><p>與那些只説母語的人相比，通曉多種語言的人可以與數百萬人交談。在軟件環境中，開發人員不會引入新的語言來達到特定的目的，也不會更好地交流。一些語言對於一項任務來説很棒，但是對於另一項任務來説卻不行，因此使用多種編程語言可以讓開發人員使用合適的工具來完成這項任務。這樣，所有的開發都是多語種的；這只是野獸的本性。</p><p>多語種環境的創建通常是漸進的和情景化的。例如，當一家企業收購一家公司時，它就承擔了該公司的技術堆棧 —— 包括其編程語言。或者，隨着技術領導的改變，新的領導者可能會將不同的技術納入其中。技術也有過時的時候，隨着時間的推移，增加了組織必須維護的編程語言和技術的數量。</p><p>多語言環境對企業來説是一把雙刃劍，既帶來好處，也帶來複雜性和挑戰。最終，如果這種情況得不到控制，多語言將會扼殺你的企業。</p><h3 id="棘手的技術繞口令" tabindex="-1">棘手的技術繞口令 <a class="header-anchor" href="#棘手的技術繞口令" aria-label="Permalink to “棘手的技術繞口令”">​</a></h3><p>如果有多種不同的技術 —— 編程語言、過時的工具和新興的技術堆棧 —— 就有複雜性。工程師團隊花更多的時間努力改進編程語言，包括許可證、安全性和依賴性。與此同時，管理層缺乏對代碼合規性的監督，無法衡量風險。</p><p>發生的情況是，企業具有不同程度的編程語言質量和工具支持的高度可變性。當你需要和十幾個人一起工作時，很難成為一種語言的專家。一個能流利地説法語和意大利語的人和一個能用八種語言串成幾個句子的人在技能水平上有很大差異。開發人員和編程語言也是如此。</p><p>隨着更多編程語言的加入，困難只會增加，導致數字巴別塔的出現。</p><p>答案是不要拿走開發人員工作所需的工具。添加新的編程語言可以建立他們的技能基礎，併為他們提供合適的設備來完成他們的工作。所以，你想對你的開發者説“是”，但是隨着越來越多的編程語言被添加到企業中，它們會拖累你的軟件開發生命週期（SDLC）。在規模上，所有這些語言和工具都可能扼殺企業。</p><p>企業應注意三個主要問題:</p><ol><li><p><strong>可見性：</strong> 團隊聚在一起執行項目，然後解散。應用程序已經發布，但從未更新 —— 為什麼要修復那些沒有被破壞的東西？因此，當發現一個關鍵漏洞時，企業可能無法瞭解哪些應用程序受到影響，這些應用程序包含哪些庫，甚至無法瞭解它們是用什麼語言構建的。這可能導致成本高昂的“勘探項目”，以確保漏洞得到適當解決。</p></li><li><p><strong>更新或編碼：</strong> 一些企業將更新和修復功能集中在一個團隊中。其他人要求每個“比薩團隊”管理自己的開發工具。無論是哪種情況，工程團隊和管理層都要付出機會成本：這些團隊沒有編碼新特性，而是不斷更新和修復開源工具中的庫，因為它們移動得如此之快。</p></li><li><p><strong>重新發明輪子：</strong> 由於代碼依賴性和庫版本不斷更新，當發現漏洞時，與應用程序原始版本相關聯的工件可能不再可用。因此，許多開發週期都被浪費在試圖重新創建一個可以修復漏洞的環境上。</p></li></ol><p>將你組織中的每種編程語言乘以這三個問題，開始時被認為是分子一樣小的東西突然看起來像珠穆朗瑪峯。就像登山者一樣，沒有合適的設備和工具，你將無法生存。</p><h3 id="找到你的羅塞塔石碑" tabindex="-1">找到你的羅塞塔石碑 <a class="header-anchor" href="#找到你的羅塞塔石碑" aria-label="Permalink to “找到你的羅塞塔石碑”">​</a></h3><p>一個全面的解決方案可以滿足 SDLC 中企業及其個人利益相關者的需求。企業可以使用以下最佳實踐創建解決方案:</p><ol><li>監控生產中運行的代碼，並根據應用程序中使用的標記組件（例如，常見漏洞和暴露組件）的風險做出響應。</li><li>定期接收更新以保持代碼的最新和無錯誤。</li><li>使用商業開源支持來獲得編程語言版本和平台的幫助，這些版本和平台已經接近尾聲，並且不受社區支持。</li><li>標準化整個企業中的特定編程語言構建，以實現跨團隊的一致環境，並最大限度地減少依賴性。</li><li>根據相關性設置何時觸發更新、警報或其他類型事件的閾值。</li><li>為您的包管理創建一個單一的可信來源；這可能需要知識淵博的技術提供商的幫助。</li><li>根據您的特定標準，只使用您需要的軟件包獲得較小的構建版本。</li></ol><p>使用這些最佳實踐，開發人員可以最大限度地利用他們的時間為企業創造更多價值，而不是執行基本的工具或構建工程任務。這將在軟件開發生命週期（SDLC）的所有環境中創建代碼一致性。由於維護編程語言和軟件包分發所需的資源更少，這也將提高效率和節約成本。這種新的操作方式將使技術人員和管理人員的生活更加輕鬆。</p><hr>',20)),a("p",null,[t[1]||(t[1]=l("via: ",-1)),e(o,{href:"https://opensource.com/article/18/11/multiple-programming-languages"},{default:i(()=>[...t[0]||(t[0]=[l("https://opensource.com/article/18/11/multiple-programming-languages",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=l("作者：",-1)),e(o,{href:"https://opensource.com/users/bartcopeland"},{default:i(()=>[...t[2]||(t[2]=[l("Bart Copeland",-1)])]),_:1}),t[7]||(t[7]=l(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[l("lujun9972",-1)])]),_:1}),t[8]||(t[8]=l(" 譯者：",-1)),e(o,{href:"https://github.com/heguangzhi"},{default:i(()=>[...t[4]||(t[4]=[l("heguangzhi",-1)])]),_:1}),t[9]||(t[9]=l(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[l("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[l("LCTT",-1)])]),_:1}),t[13]||(t[13]=l(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[l("Linux中國",-1)])]),_:1}),t[14]||(t[14]=l(" 榮譽推出",-1))])])}const _=r(g,[["render",m]]);export{L as __pageData,_ as default};
